16	package io.helidon.tracing.opentelemetry;
17	
18	import java.util.concurrent.atomic.AtomicBoolean;
19	
20	import io.helidon.tracing.Scope;
21	
22	class OpenTelemetryScope implements Scope {
23	    private final io.opentelemetry.context.Scope delegate;
24	    private final AtomicBoolean closed = new AtomicBoolean();
25	
26	    OpenTelemetryScope(io.opentelemetry.context.Scope scope) {
27	        delegate = scope;
28	    }
29	
30	    @Override
31	    public void close() {
32	        if (closed.compareAndSet(false, true) && delegate != null) {
33	            delegate.close();
34	        }
35	    }
36	
37	    @Override
38	    public boolean isClosed() {
39	        return closed.get();
40	    }
41	}
