16	package io.helidon.tracing.opentelemetry;
17	
18	import java.time.Instant;
19	
20	import io.helidon.tracing.Span;
21	import io.helidon.tracing.SpanContext;
22	
23	import io.opentelemetry.api.trace.SpanBuilder;
24	import io.opentelemetry.api.trace.SpanKind;
25	import io.opentelemetry.context.Context;
26	
27	class OpenTelemetrySpanBuilder implements Span.Builder<OpenTelemetrySpanBuilder> {
28	    private final SpanBuilder spanBuilder;
29	    private boolean parentSet;
30	
31	    OpenTelemetrySpanBuilder(SpanBuilder spanBuilder) {
32	        this.spanBuilder = spanBuilder;
33	    }
34	
35	    @Override
36	    public Span build() {
37	        return start();
38	    }
39	
40	    @Override
41	    public OpenTelemetrySpanBuilder parent(SpanContext spanContext) {
42	        this.parentSet = true;
43	        spanContext.asParent(this);
44	        return this;
45	    }
46	
47	    @Override
48	    public OpenTelemetrySpanBuilder kind(Span.Kind kind) {
49	        switch (kind) {
50	        case SERVER -> spanBuilder.setSpanKind(SpanKind.SERVER);
51	        case CLIENT -> spanBuilder.setSpanKind(SpanKind.CLIENT);
52	        case PRODUCER -> spanBuilder.setSpanKind(SpanKind.PRODUCER);
53	        case CONSUMER -> spanBuilder.setSpanKind(SpanKind.CONSUMER);
54	        default -> spanBuilder.setSpanKind(SpanKind.INTERNAL);
55	        }
56	
57	        return this;
58	    }
59	
60	    @Override
61	    public OpenTelemetrySpanBuilder tag(String key, String value) {
62	        spanBuilder.setAttribute(key, value);
63	        return this;
64	    }
65	
66	    @Override
67	    public OpenTelemetrySpanBuilder tag(String key, Boolean value) {
68	        spanBuilder.setAttribute(key, value);
69	        return this;
70	    }
71	
72	    @Override
73	    public OpenTelemetrySpanBuilder tag(String key, Number value) {
74	        if (value instanceof Double || value instanceof Float) {
75	            spanBuilder.setAttribute(key, value.doubleValue());
76	        } else {
77	            spanBuilder.setAttribute(key, value.longValue());
78	        }
79	
80	        return this;
81	    }
82	
83	    @Override
84	    public Span start(Instant instant) {
85	        if (!parentSet) {
86	            spanBuilder.setNoParent();
87	        }
88	        spanBuilder.setStartTimestamp(instant);
89	        io.opentelemetry.api.trace.Span span = spanBuilder.startSpan();
90	        return new OpenTelemetrySpan(span);
91	    }
92	
93	    // used to set open telemetry context as parent, to be equivalent in function to
94	    // #parent(SpanContext)
95	    void parent(Context context) {
96	        this.parentSet = true;
97	        this.spanBuilder.setParent(context);
98	    }
99	}
