36	class OpenTelemetryTracer implements Tracer {
37	    private static final TextMapGetter GETTER = new Getter();
38	    private static final TextMapSetter SETTER = new Setter();
39	    private final OpenTelemetry telemetry;
40	    private final io.opentelemetry.api.trace.Tracer delegate;
41	    private final boolean enabled;
42	    private final TextMapPropagator propagator;
43	    private final Map<String, String> tags;
44	
45	    OpenTelemetryTracer(OpenTelemetry telemetry, io.opentelemetry.api.trace.Tracer tracer, Map<String, String> tags) {
46	        this.telemetry = telemetry;
47	        this.delegate = tracer;
48	        this.enabled = !tracer.getClass().getSimpleName().equals("DefaultTracer");
49	        this.propagator = telemetry.getPropagators().getTextMapPropagator();
50	        this.tags = tags;
51	    }
52	
53	    static Builder builder() {
54	        return new Builder();
55	    }
56	
57	    @Override
58	    public boolean enabled() {
59	        return enabled;
60	    }
61	
62	    @Override
63	    public Span.Builder<?> spanBuilder(String name) {
64	        OpenTelemetrySpanBuilder builder = new OpenTelemetrySpanBuilder(delegate.spanBuilder(name));
65	        tags.forEach(builder::tag);
66	        return builder;
67	    }
68	
69	    @Override
70	    public Optional<SpanContext> extract(HeaderProvider headersProvider) {
71	        Context context = propagator.extract(Context.current(), headersProvider, GETTER);
72	
73	        return Optional.ofNullable(context)
74	                .map(OpenTelemetrySpanContext::new);
75	    }
76	
77	    @Override
78	    public void inject(SpanContext spanContext, HeaderProvider inboundHeadersProvider, HeaderConsumer outboundHeadersConsumer) {
79	        propagator.inject(((OpenTelemetrySpanContext) spanContext).openTelemetry(), outboundHeadersConsumer, SETTER);
80	    }
81	
82	    @Override
83	    public <T> T unwrap(Class<T> tracerClass) {
84	        if (tracerClass.isAssignableFrom(delegate.getClass())) {
85	            return tracerClass.cast(delegate);
86	        }
87	        throw new IllegalArgumentException("Cannot provide an instance of " + tracerClass.getName()
88	                                                   + ", telemetry tracer is: " + delegate.getClass().getName());
89	    }
90	
91	    static class Builder implements TracerBuilder<Builder> {
92	        private OpenTelemetry ot;
93	        private String serviceName = "helidon-service";
94	        private boolean registerGlobal;
95	
96	        @Override
97	        public Tracer build() {
98	            if (ot == null) {
99	                ot = GlobalOpenTelemetry.get();
100	            }
101	            io.opentelemetry.api.trace.Tracer tracer = ot.getTracer(serviceName);
102	            Tracer result = new OpenTelemetryTracer(ot, tracer, Map.of());
103	            if (registerGlobal) {
104	                Tracer.global(result);
105	            }
106	            return result;
107	        }
108	
109	        Builder openTelemetry(OpenTelemetry ot) {
110	            this.ot = ot;
111	            return this;
112	        }
