36	/**
37	 * Service loader provider implementation for {@link io.helidon.tracing.spi.TracerProvider}.
38	 */
39	@Priority(Prioritized.DEFAULT_PRIORITY + 1000)
40	public class OpenTelemetryTracerProvider implements TracerProvider {
41	    private static final System.Logger LOGGER = System.getLogger(OpenTelemetryTracerProvider.class.getName());
42	
43	    private static final AtomicReference<Tracer> CONFIGURED_TRACER = new AtomicReference<>();
44	    private static final AtomicBoolean GLOBAL_SET = new AtomicBoolean();
45	    private static final LazyValue<Tracer> GLOBAL_TRACER;
46	
47	    static {
48	        GLOBAL_TRACER = LazyValue.create(() -> {
49	            // try to get from configured global tracer
50	            Tracer tracer = CONFIGURED_TRACER.get();
51	            if (tracer != null) {
52	                return tracer;
53	            }
54	            Context global = Contexts.globalContext();
55	            return global.get(OpenTelemetryTracer.class)
56	                    .map(Tracer.class::cast)
57	                    .orElseGet(() -> {
58	                        if (LOGGER.isLoggable(System.Logger.Level.TRACE)) {
59	                            LOGGER.log(System.Logger.Level.TRACE, "Global tracer is not registered. Register it through "
60	                                    + "Tracer.global(HelidonOpenTelemetry.create(ot, tracer). Using global open telemetry");
61	                        }
62	                        OpenTelemetry ot = GlobalOpenTelemetry.get();
63	                        return new OpenTelemetryTracer(ot, ot.getTracer("helidon-service"), Map.of());
64	                    });
65	        });
66	    }
67	
68	    /**
69	     * Register global tracer.
70	     *
71	     * @param tracer global tracer
72	     */
73	    public static void globalTracer(Tracer tracer) {
74	        GLOBAL_SET.set(true);
75	        CONFIGURED_TRACER.set(tracer);
76	    }
77	
78	    /**
79	     * Registered global tracer, or tracer from global open telemetry.
80	     *
81	     * @return tracer
82	     */
83	    public static Tracer globalTracer() {
84	        return GLOBAL_TRACER.get();
85	    }
86	
87	    @Override
88	    public TracerBuilder<?> createBuilder() {
89	        return OpenTelemetryTracer.builder();
90	    }
91	
92	    @Override
93	    public Tracer global() {
94	        return globalTracer();
95	    }
96	
97	    @Override
98	    public void global(Tracer tracer) {
99	        if (tracer instanceof OpenTelemetryTracer ott) {
100	            globalTracer(ott);
101	        }
102	        throw new IllegalArgumentException("Tracer must be an instance of Helidon OpenTelemetry tracer. "
103	                                                   + "Please use HelidonOpenTelemetry to create such instance");
104	    }
105	
106	    @Override
107	    public Optional<Span> currentSpan() {
108	        return Optional.ofNullable(io.opentelemetry.api.trace.Span.current()).map(HelidonOpenTelemetry::create);
109	    }
110	
111	    @Override
112	    public boolean available() {
113	        return GLOBAL_SET.get();
114	    }
115	}
