28	/**
29	 * Open Telemetry factory methods to create wrappers for Open Telemetry types.
30	 */
31	public final class HelidonOpenTelemetry {
32	
33	    private static final System.Logger LOGGER = System.getLogger(HelidonOpenTelemetry.class.getName());
34	    static final String OTEL_AGENT_PRESENT_PROPERTY = "otel.agent.present";
35	    static final String IO_OPENTELEMETRY_JAVAAGENT = "io.opentelemetry.javaagent";
36	    private HelidonOpenTelemetry() {
37	    }
38	    /**
39	     * Wrap an open telemetry tracer.
40	     *
41	     * @param telemetry open telemetry instance
42	     * @param tracer    tracer
43	     * @param tags      tracer tags
44	     * @return Helidon {@link io.helidon.tracing.Tracer}
45	     */
46	    public static OpenTelemetryTracer create(OpenTelemetry telemetry, Tracer tracer, Map<String, String> tags) {
47	        return new OpenTelemetryTracer(telemetry, tracer, tags);
48	    }
49	
50	    /**
51	     * Wrap an open telemetry span.
52	     *
53	     * @param span open telemetry span
54	     * @return Helidon {@link io.helidon.tracing.Span}
55	     */
56	    public static io.helidon.tracing.Span create(Span span) {
57	        return new OpenTelemetrySpan(span);
58	    }
59	
60	
61	    /**
62	     * Check if OpenTelemetry is present by indirect properties.
63	     * This class does best explicit check if OTEL_AGENT_PRESENT_PROPERTY config property is set and uses its
64	     * value to set the behaviour of OpenTelemetry producer.
65	     *
66	     * If the value is not explicitly set, the detector does best effort to estimate indirect means if the agent is present.
67	     * This detector may stop working if OTEL changes the indirect indicators.
68	     */
69	    public static final class AgentDetector {
70	
71	        //Private constructor for a utility class.
72	        private AgentDetector() {
73	        }
74	
75	        /**
76	         * Check if the OTEL Agent is present.
77	         *
78	         * @param config Configuration
79	         * @return boolean
80	         */
81	        public static boolean isAgentPresent(Config config) {
82	
83	            //Explicitly check if agent property is set
84	            if (config != null) {
85	                Optional<Boolean> agentPresent = config.get(OTEL_AGENT_PRESENT_PROPERTY).asBoolean().asOptional();
86	                if (agentPresent.isPresent()) {
87	                    return agentPresent.get();
88	                }
89	            }
90	
91	            if (checkContext() || checkSystemProperties()) {
92	                if (LOGGER.isLoggable(System.Logger.Level.INFO)) {
93	                    LOGGER.log(System.Logger.Level.INFO, "OpenTelemetry Agent detected");
94	                }
95	                return true;
96	            }
97	            return false;
98	        }
99	
100	        private static boolean checkSystemProperties() {
101	            return System.getProperties().stringPropertyNames()
102	                    .stream()
103	                    .anyMatch(property -> property.contains(IO_OPENTELEMETRY_JAVAAGENT));
104	        }
105	
106	        private static boolean checkContext() {
107	            return io.opentelemetry.context.Context.current().getClass().getName().contains("agent");
108	        }
109	    }
110	}
